-- Carga 1 de 26 de la herramienta arbitros-cr. La arma herramientas/arbitros-cr.py: no se edita a mano.
-- Lee las respuestas 18998 a 18998 del buscador de chess-results (net._http_response).
with r as (select id, substr(content, strpos(content, '<table class="CRs2"')) t from net._http_response
  where id between 18998 and 18998 and strpos(content, '<table class="CRs2"') > 0),
filas as (select f from r, regexp_split_to_table(substr(t, 1, strpos(t, '</table>')), '<tr class="CR') f where f ~ '^n?g[12]">'),
celdas as (select regexp_split_to_array(f, '</t[dh]>') c from filas),
t as (select distinct on (btrim(regexp_replace(c[19], '<[^>]+>', '', 'g'))::int) btrim(regexp_replace(c[19], '<[^>]+>', '', 'g'))::int clave, c from celdas
  where btrim(regexp_replace(c[19], '<[^>]+>', '', 'g')) ~ '^\d+$')
insert into public.arbitros_cr_cr (clave, nombre, inicio, fin, lugar, control, rondas, jugadores, pais)
select clave, coalesce(nullif(btrim(regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce((select string_agg(case when m[1] is not null then case when m[1]::int between 32 and 8999 then chr(m[1]::int) else '' end when m[2] is not null then '' else m[3] end, '' order by o) from regexp_matches(regexp_replace(c[2], '<[^>]+>', '', 'g'), '&#(\d+);|&#x([0-9A-Fa-f]+);|([^&]+|&)', 'g') with ordinality r(m, o)), ''), '&quot;', '"'), '&#39;', ''''), '&uuml;', 'ü'), '&Ouml;', 'Ö'), '&copy;', '©'), '&lt;', '<'), '&gt;', '>'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), '\s+', ' ', 'g')), ''), '(sin nombre)'),
  replace(btrim(regexp_replace(c[6], '<[^>]+>', '', 'g')), '/', '-')::date,
  nullif(replace(btrim(regexp_replace(c[7], '<[^>]+>', '', 'g')), '/', '-'), '')::date,
  left(btrim(regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce((select string_agg(case when m[1] is not null then case when m[1]::int between 32 and 8999 then chr(m[1]::int) else '' end when m[2] is not null then '' else m[3] end, '' order by o) from regexp_matches(regexp_replace(c[13], '<[^>]+>', '', 'g'), '&#(\d+);|&#x([0-9A-Fa-f]+);|([^&]+|&)', 'g') with ordinality r(m, o)), ''), '&quot;', '"'), '&#39;', ''''), '&uuml;', 'ü'), '&Ouml;', 'Ö'), '&copy;', '©'), '&lt;', '<'), '&gt;', '>'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), '\s+', ' ', 'g')), 200), left(btrim(regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(coalesce((select string_agg(case when m[1] is not null then case when m[1]::int between 32 and 8999 then chr(m[1]::int) else '' end when m[2] is not null then '' else m[3] end, '' order by o) from regexp_matches(regexp_replace(c[14], '<[^>]+>', '', 'g'), '&#(\d+);|&#x([0-9A-Fa-f]+);|([^&]+|&)', 'g') with ordinality r(m, o)), ''), '&quot;', '"'), '&#39;', ''''), '&uuml;', 'ü'), '&Ouml;', 'Ö'), '&copy;', '©'), '&lt;', '<'), '&gt;', '>'), '&nbsp;', ' '), '&amp;', '&'), chr(160), ' '), '\s+', ' ', 'g')), 200),
  coalesce(nullif(btrim(regexp_replace(c[17], '<[^>]+>', '', 'g')), '')::smallint, 0),
  coalesce(nullif(btrim(regexp_replace(c[18], '<[^>]+>', '', 'g')), '')::int, 0),
  coalesce(substring(btrim(regexp_replace(c[3], '<[^>]+>', '', 'g')) from '^[A-Z]{3}$'), 'CRC')
from t where clave = any('{1328730,1328731,1328733,1328734,1328735,1328736,1328737,1328738,1328740,1328741,1328742,1328743,1328760,1328761,1328763,1328766,1328770,1328772,1328773,1328775,1329122,1329127,1329131,1329136,1329144,1329145,1329147,1329148,1329149,1329150,1329151,1329153,1329154,1329155,1329156,1329158,1330521,1330523,1330525,1330527,1340349,1340481,1341011,1341014,1341458,1341860,1343466,1345662,1349862,1356842,1356843,1356844,1356845,1356846,1356847,1356848,1356849,1356850,1356851,1356852,1357737,1361495,1362525,1364160,1365365,1366341,1367045,1367047,1369001,1369387,1369389,1370826,1371417,1371575,1371584,1371834,1371857,1371879,1373296,1373297,1373298,1373301,1373303,1373305,1373308,1373643,1373648,1373721,1373723,1373725,1373964,1373965,1373970,1373971,1373988,1373993,1374240,1374374,1374377,1374449,1374480,1374481,1374482,1374483,1374484,1374496,1374507,1374512,1374514,1374526,1374529,1374616,1374618,1374619,1374627,1374628,1374629,1374630,1374635,1374637,1374639,1374700,1374702,1374706,1374708,1374709,1374712,1374713,1374717,1374766,1374773,1375031,1375033,1375034,1375036,1375038,1375112,1375274,1375296,1375298,1375305,1375307,1375308,1375310,1375416,1375418,1375422,1375614,1376728,1376777,1376778,1378806,1378807,1378810,1378850,1378851,1379400,1379402,1379404,1379408,1379418,1379423,1379425,1379429,1379431,1379769,1379771,1379773,1379785,1379822,1379833,1379841,1379843,1379848,1380086,1380088,1380090,1380092,1380093,1380094,1380162,1380182,1380183,1380185,1380186,1380189,1380196,1380420,1380422,1380423,1380424,1380430,1381739,1381826,1381865,1381868,1381889,1381909,1381929,1381933,1381948,1381975,1382091,1382678,1383126,1383129,1383638,1384310,1384312,1384317,1384319,1384684,1384699,1384701,1384705,1384710,1384744,1384745,1384748,1384750,1384753,1385295,1385299,1385328,1385344,1385347,1387503,1387504,1387512,1387518,1387898,1387900,1387917,1387919,1387923,1387927,1388002,1388003,1388118,1388122,1388128,1388132,1388133,1388134,1388369,1388379,13883